export const SPECIES: Readonly<Record<string, Species>> = Object.freeze(
  Object.fromEntries(SPECIES_LIST.map((s) => [s.id, s])),
);

export function getSpecies(id: string): Species {
  const s = SPECIES[id];
  if (!s) throw new Error(`unknown species: ${id}`);
  return s;
}

export function speciesByDex(dex: number): Species | undefined {
  return SPECIES_LIST.find((s) => s.dex === dex);
}
